from __future__ import annotations

import ast
import functools
import inspect
import os
import pprint
import sys
import warnings
from contextlib import contextmanager
from datetime import datetime
from os.path import basename, realpath
from textwrap import dedent
from typing import Any, Callable, Generator, List, Sequence, Tuple, Type, TypeVar, Union, cast

import colorama
import executing
from pygments import highlight
from pygments.formatters import Terminal256Formatter

try:
    from pygments.formatters import TerminalTrueColorFormatter
except ImportError:  # pragma: no cover
    TerminalTrueColorFormatter = None  # type: ignore[assignment]

try:
    from pygments.lexers import Python3Lexer as Py3Lexer
except ImportError:  # pragma: no cover
    from pygments.lexers import PythonLexer as Py3Lexer

from .coloring import SolarizedDark


_absent = object()
_T = TypeVar("_T")


def bindStaticVariable(name: str, value: Any) -> Callable[[Callable[..., _T]], Callable[..., _T]]:
    def decorator(fn: Callable[..., _T]) -> Callable[..., _T]:
        setattr(fn, name, value)
        return fn

    return decorator


def _should_use_truecolor() -> bool:
    return os.environ.get("COLORTERM", "").lower() in {"24bit", "truecolor"}


def _make_formatter() -> Terminal256Formatter:
    if TerminalTrueColorFormatter is not None and _should_use_truecolor():
        return TerminalTrueColorFormatter(style=SolarizedDark)  # type: ignore[return-value]
    return Terminal256Formatter(style=SolarizedDark)


def hasNonAsciiChars(s: str) -> bool:
    return any(ord(char) > 127 for char in s)


@bindStaticVariable("formatter", _make_formatter())
@bindStaticVariable("lexer", Py3Lexer(ensurenl=False))
def colorize(s: str) -> str:
    self = colorize

    if hasNonAsciiChars(s):
        return s

    return highlight(s, self.lexer, self.formatter)


@contextmanager
def supportTerminalColorsInWindows() -> Generator[None, None, None]:
    if sys.platform.startswith("win"):
        colorama.init()
        try:
            yield
        finally:
            colorama.deinit()
    else:
        yield


def stderrPrint(*args: object) -> None:
    print(*args, file=sys.stderr)


def stdoutPrint(*args: object) -> None:
    print(*args)


def isLiteral(s: str) -> bool:
    try:
        ast.literal_eval(s)
    except Exception:
        return False
    return True


def colorizedStderrPrint(s: str) -> None:
    colored = colorize(s)
    with supportTerminalColorsInWindows():
        stderrPrint(colored)


def colorizedStdoutPrint(s: str) -> None:
    colored = colorize(s)
    with supportTerminalColorsInWindows():
        stdoutPrint(colored)


DEFAULT_PREFIX = "ic| "
DEFAULT_LINE_WRAP_WIDTH = 70
DEFAULT_CONTEXT_DELIMITER = "- "
DEFAULT_OUTPUT_FUNCTION = colorizedStderrPrint
DEFAULT_ARG_TO_STRING_FUNCTION = pprint.pformat

NO_SOURCE_AVAILABLE_WARNING_MESSAGE = (
    "Failed to access the underlying source code for analysis. Was ic() "
    "invoked in a REPL (e.g. from the command line), a frozen application "
    "(e.g. packaged with PyInstaller), or did the underlying source code "
    "change during execution?"
)


def callOrValue(obj: Union[Callable[[], _T], _T]) -> _T:
    return obj() if callable(obj) else obj


class Source(executing.Source):
    def get_text_with_indentation(self, node: ast.AST) -> str:
        result = self.asttokens().get_text(node)
        if "\n" in result:
            result = " " * node.first_token.start[1] + result  # type: ignore[attr-defined]
            result = dedent(result)
        return result.strip()


def prefixLines(prefix: str, s: str, startAtLine: int = 0) -> List[str]:
    lines = s.splitlines()
    for i in range(startAtLine, len(lines)):
        lines[i] = prefix + lines[i]
    return lines


def prefixFirstLineIndentRemaining(prefix: str, s: str) -> List[str]:
    indent = " " * len(prefix)
    lines = prefixLines(indent, s, startAtLine=1)
    lines[0] = prefix + lines[0]
    return lines


def formatPair(prefix: str, arg: Union[str, object], value: str) -> str:
    if arg is _absent:
        argLines: List[str] = []
        valuePrefix = prefix
    else:
        argLines = prefixFirstLineIndentRemaining(prefix, cast(str, arg))
        valuePrefix = argLines[-1] + ": "

    looksLikeAString = len(value) >= 2 and (value[0] + value[-1]) in {"''", '""'}
    if looksLikeAString:
        valueLines = prefixLines(" ", value, startAtLine=1)
        value = "\n".join(valueLines)

    valueLines = prefixFirstLineIndentRemaining(valuePrefix, value)
    lines = argLines[:-1] + valueLines
    return "\n".join(lines)


def singledispatch(func: Callable[..., str]) -> Callable[..., str]:
    dispatched = functools.singledispatch(func)
    closure = dict(
        zip(
            dispatched.register.__code__.co_freevars,
            cast(Tuple[Any, ...], dispatched.register.__closure__),
        )
    )
    registry = closure["registry"].cell_contents
    dispatch_cache = closure["dispatch_cache"].cell_contents

    def unregister(cls: Type[Any]) -> None:
        del registry[cls]
        dispatch_cache.clear()

    dispatched.unregister = unregister  # type: ignore[attr-defined]
    return dispatched


@singledispatch
def argumentToString(obj: object) -> str:
    s = DEFAULT_ARG_TO_STRING_FUNCTION(obj)
    return s.replace("\\n", "\n")


@argumentToString.register(str)
def _(obj: str) -> str:
    if "\n" in obj:
        return "'''" + obj + "'''"
    return "'" + obj.replace("\\", "\\\\") + "'"


class IceCreamDebugger:
    _pairDelimiter = ", "
    lineWrapWidth = DEFAULT_LINE_WRAP_WIDTH
    contextDelimiter = DEFAULT_CONTEXT_DELIMITER

    def __init__(
        self,
        prefix: Union[str, Callable[[], str]] = DEFAULT_PREFIX,
        outputFunction: Callable[[str], None] = DEFAULT_OUTPUT_FUNCTION,
        argToStringFunction: Callable[[object], str] = argumentToString,
        includeContext: bool = False,
        contextAbsPath: bool = False,
    ) -> None:
        self.enabled = True
        self.prefix = prefix
        self.includeContext = includeContext
        self.outputFunction = outputFunction
        self.argToStringFunction = argToStringFunction
        self.contextAbsPath = contextAbsPath

    def __call__(self, *args: object) -> object:
        if self.enabled:
            currentFrame = inspect.currentframe()
            assert currentFrame is not None and currentFrame.f_back is not None
            callFrame = currentFrame.f_back
            self.outputFunction(self._format(callFrame, *args))

        if not args:
            passthrough = None
        elif len(args) == 1:
            passthrough = args[0]
        else:
            passthrough = args

        return passthrough

    def format(self, *args: object) -> str:
        currentFrame = inspect.currentframe()
        assert currentFrame is not None and currentFrame.f_back is not None
        callFrame = currentFrame.f_back
        return self._format(callFrame, *args)

    def _format(self, callFrame: Any, *args: object) -> str:
        prefix = callOrValue(self.prefix)
        context = self._formatContext(callFrame)

        if not args:
            return prefix + context + self._formatTime()

        if not self.includeContext:
            context = ""

        return self._formatArgs(callFrame, prefix, context, args)

    def _formatArgs(
        self,
        callFrame: Any,
        prefix: str,
        context: str,
        args: Sequence[object],
    ) -> str:
        callNode = Source.executing(callFrame).node
        if callNode is not None:
            assert isinstance(callNode, ast.Call)
            source = cast(Source, Source.for_frame(callFrame))
            sanitizedArgStrs = [
                source.get_text_with_indentation(arg)
                for arg in callNode.args
            ]
        else:
            warnings.warn(
                NO_SOURCE_AVAILABLE_WARNING_MESSAGE,
                category=RuntimeWarning,
                stacklevel=4,
            )
            sanitizedArgStrs = [_absent] * len(args)

        pairs = list(zip(sanitizedArgStrs, args))
        return self._constructArgumentOutput(prefix, context, pairs)

    def _constructArgumentOutput(
        self,
        prefix: str,
        context: str,
        pairs: Sequence[Tuple[Union[str, object], object]],
    ) -> str:
        def argPrefix(arg: str) -> str:
            return "%s: " % arg

        renderedPairs = [(arg, self.argToStringFunction(value)) for arg, value in pairs]
        pairStrs = [
            value if (arg is _absent or isLiteral(cast(str, arg)))
            else (argPrefix(cast(str, arg)) + value)
            for arg, value in renderedPairs
        ]

        allArgsOnOneLine = self._pairDelimiter.join(pairStrs)
        multilineArgs = len(allArgsOnOneLine.splitlines()) > 1

        contextDelimiter = self.contextDelimiter if context else ""
        allPairs = prefix + context + contextDelimiter + allArgsOnOneLine
        firstLineTooLong = len(allPairs.splitlines()[0]) > self.lineWrapWidth

        if multilineArgs or firstLineTooLong:
            if context:
                lines = [prefix + context] + [
                    formatPair(" " * len(prefix), arg, value)
                    for arg, value in renderedPairs
                ]
            else:
                argLines = [
                    formatPair("", arg, value)
                    for arg, value in renderedPairs
                ]
                lines = prefixFirstLineIndentRemaining(prefix, "\n".join(argLines))
        else:
            lines = [prefix + context + contextDelimiter + allArgsOnOneLine]

        return "\n".join(lines)

    def _formatContext(self, callFrame: Any) -> str:
        filename, lineNumber, parentFunction = self._getContext(callFrame)
        if parentFunction != "<module>":
            parentFunction = "%s()" % parentFunction
        return "%s:%s in %s" % (filename, lineNumber, parentFunction)

    def _formatTime(self) -> str:
        return " at %s" % datetime.now().strftime("%H:%M:%S.%f")[:-3]

    def _getContext(self, callFrame: Any) -> Tuple[str, int, str]:
        frameInfo = inspect.getframeinfo(callFrame)
        lineNumber = frameInfo.lineno
        parentFunction = frameInfo.function
        filepath = (realpath if self.contextAbsPath else basename)(frameInfo.filename)
        return filepath, lineNumber, parentFunction

    def enable(self) -> None:
        self.enabled = True

    def disable(self) -> None:
        self.enabled = False

    def use_stdout(self) -> None:
        self.outputFunction = colorizedStdoutPrint

    def use_stderr(self) -> None:
        self.outputFunction = colorizedStderrPrint

    def configureOutput(
        self,
        prefix: object = _absent,
        outputFunction: object = _absent,
        argToStringFunction: object = _absent,
        includeContext: object = _absent,
        contextAbsPath: object = _absent,
        lineWrapWidth: object = _absent,
    ) -> None:
        noParameterProvided = all(
            value is _absent
            for key, value in locals().items()
            if key != "self"
        )
        if noParameterProvided:
            raise TypeError("configureOutput() missing at least one argument")

        if prefix is not _absent:
            self.prefix = prefix

        if outputFunction is not _absent:
            self.outputFunction = cast(Callable[[str], None], outputFunction)

        if argToStringFunction is not _absent:
            self.argToStringFunction = cast(Callable[[object], str], argToStringFunction)

        if includeContext is not _absent:
            self.includeContext = cast(bool, includeContext)

        if contextAbsPath is not _absent:
            self.contextAbsPath = cast(bool, contextAbsPath)

        if lineWrapWidth is not _absent:
            self.lineWrapWidth = cast(int, lineWrapWidth)


ic = IceCreamDebugger()

__all__ = [
    "DEFAULT_ARG_TO_STRING_FUNCTION",
    "DEFAULT_CONTEXT_DELIMITER",
    "DEFAULT_LINE_WRAP_WIDTH",
    "DEFAULT_OUTPUT_FUNCTION",
    "DEFAULT_PREFIX",
    "IceCreamDebugger",
    "NO_SOURCE_AVAILABLE_WARNING_MESSAGE",
    "Source",
    "argumentToString",
    "callOrValue",
    "colorize",
    "colorizedStderrPrint",
    "colorizedStdoutPrint",
    "formatPair",
    "ic",
    "isLiteral",
    "prefixFirstLineIndentRemaining",
    "prefixLines",
    "stderrPrint",
    "stdoutPrint",
    "supportTerminalColorsInWindows",
]

